#!/usr/bin/env python3
"""Post a "weekly" issue listing merged pull requests and opened/closed issues.

Usage:
  weekly_update.py --scheduled "<cron>"           (Weekly update workflow)
  weekly_update.py --start YYYY-MM-DD --end YYYY-MM-DD   (Maintenance button)
  add --dry-run to print the issue instead of posting it.

Scheduled runs cover the previous Friday 4:01 PM to this Friday 4:00 PM,
America/Chicago. GitHub cron runs in UTC only, so the workflow fires at both
21:00 and 22:00 UTC on Fridays and this script keeps only the one that is
4:00 PM in Chicago (21:00 during daylight saving, 22:00 otherwise). The window
is computed from the calendar, not the clock, so a late-running job still
reports the same week.

Manual runs cover the start date 00:00 through the end date 23:59, Chicago time.

Nothing here is written by AI: each pull request's line is the opening
paragraph of its own description. Needs `gh` signed in (GH_TOKEN) and
GITHUB_REPOSITORY set. Standard library only.
"""

import argparse
import json
import os
import subprocess
import sys
from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

CHICAGO = ZoneInfo("America/Chicago")
LABEL = "weekly"
# Cron string -> the UTC offset (hours) Chicago must have for that run to be 4:00 PM.
SCHEDULES = {"0 21 * * 5": -5, "0 22 * * 5": -6}


def friday_on_or_before(day):
    return day - timedelta(days=(day.weekday() - 4) % 7)


def scheduled_window(cron, now_utc):
    """Return (start, end) for a scheduled run, or None if this run should skip."""
    if cron not in SCHEDULES:
        sys.exit(f"unknown schedule {cron!r}")
    friday = friday_on_or_before(now_utc.astimezone(CHICAGO).date())
    end = datetime.combine(friday, time(16, 0), CHICAGO)
    if end.utcoffset() != timedelta(hours=SCHEDULES[cron]):
        return None
    return end - timedelta(days=7), end


def manual_window(start_day, end_day):
    if end_day < start_day:
        sys.exit("end date is before start date")
    start = datetime.combine(start_day, time(0, 0), CHICAGO)
    end = datetime.combine(end_day + timedelta(days=1), time(0, 0), CHICAGO)
    return start - timedelta(seconds=1), end - timedelta(seconds=1)


def in_window(stamp, start, end):
    """Start is exclusive (Friday 4:00 PM belongs to the earlier week), end inclusive."""
    when = datetime.fromisoformat(stamp.replace("Z", "+00:00"))
    return start < when <= end


def summary(body):
    """Opening paragraph of a pull request description, before Tested/footer lines."""
    paragraph = []
    for line in (body or "").replace("\r\n", "\n").split("\n"):
        text = line.strip()
        lowered = text.lower().lstrip("*#_ ")
        if lowered.startswith(("tested", "not tested", "generated by")) or text == "---":
            break
        if not text:
            if paragraph:
                break
            continue
        paragraph.append(text)
    return " ".join(paragraph) or "(no description)"


def gh(*args, body=None):
    cmd = ["gh", "api", *args]
    if body is not None:
        cmd += ["--input", "-"]
    result = subprocess.run(cmd, input=json.dumps(body) if body is not None else None,
                            capture_output=True, text=True)
    if result.returncode != 0:
        sys.exit(f"gh failed: {' '.join(args)}\n{result.stderr.strip()}")
    return json.loads(result.stdout) if result.stdout.strip() else {}


def utc(moment):
    return moment.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def closed_pulls(repo, start):
    """Closed pull requests updated since start (merging updates a PR, so none are missed)."""
    found, page = [], 1
    while True:
        items = gh(f"repos/{repo}/pulls?state=closed&sort=updated&direction=desc"
                   f"&per_page=100&page={page}")
        found += items
        if not items or not in_window(items[-1]["updated_at"], start, datetime.max.replace(
                tzinfo=timezone.utc)):
            return found
        page += 1


def issues_since(repo, start, labels=""):
    """Issues (not pull requests) updated since start; opening or closing updates an issue."""
    found, page = [], 1
    while True:
        items = gh(f"repos/{repo}/issues?state=all&since={utc(start)}&labels={labels}"
                   f"&per_page=100&page={page}")
        found += [i for i in items if "pull_request" not in i]
        if len(items) < 100:
            return found
        page += 1


def is_weekly(issue):
    return any(x["name"] == LABEL for x in issue["labels"])


def collect(repo, start, end):
    merged = [p for p in closed_pulls(repo, start)
              if p["merged_at"] and in_window(p["merged_at"], start, end)]
    issues = [i for i in issues_since(repo, start) if not is_weekly(i)]
    opened = [i for i in issues if in_window(i["created_at"], start, end)]
    closed = [i for i in issues if i["closed_at"] and in_window(i["closed_at"], start, end)]
    merged.sort(key=lambda p: p["merged_at"])
    opened.sort(key=lambda i: i["number"])
    closed.sort(key=lambda i: i["number"])
    return merged, opened, closed


def label_of(moment):
    local = moment.astimezone(CHICAGO)
    return f"{local:%a %b} {local.day}, {local:%Y} {local:%I:%M %p %Z}".replace(" 0", " ")


def render(start, end, merged, opened, closed):
    first = start + timedelta(minutes=1) if start.second == 0 else start + timedelta(seconds=1)
    title = f"Weekly update: {first.astimezone(CHICAGO):%b} {first.astimezone(CHICAGO).day} to " \
            f"{end.astimezone(CHICAGO):%b} {end.astimezone(CHICAGO).day}, {end.astimezone(CHICAGO):%Y}"
    lines = [f"Covers {label_of(first)} to {label_of(end)}.",
             "", f"## Pull requests merged ({len(merged)})"]
    lines += [f"- **#{p['number']} {p['title']}**: {summary(p['body'])}" for p in merged] or ["None."]
    lines += ["", f"## Issues opened ({len(opened)})"]
    lines += [f"- #{i['number']} {i['title']}" for i in opened] or ["None."]
    lines += ["", f"## Issues closed ({len(closed)})"]
    reasons = {"not_planned": " (not planned)", "duplicate": " (duplicate)"}
    lines += [f"- #{i['number']} {i['title']}{reasons.get(i.get('state_reason'), '')}"
              for i in closed] or ["None."]
    lines += ["", "_Posted by the Weekly update workflow from pull request and issue data._"]
    return title, "\n".join(lines) + "\n"


def post(repo, title, body, dry):
    existing = issues_since(repo, datetime(2000, 1, 1, tzinfo=timezone.utc), labels=LABEL)
    if any(i["title"] == title for i in existing):
        print(f"skip: an issue titled {title!r} already exists")
        return
    if dry:
        print("would create issue:", title, "\n", body, sep="")
        return
    labels = [x["name"] for x in gh(f"repos/{repo}/labels?per_page=100")]
    if LABEL not in labels:
        gh(f"repos/{repo}/labels", "-X", "POST",
           body={"name": LABEL, "color": "bfd4f2", "description": "Weekly update"})
    issue = gh(f"repos/{repo}/issues", "-X", "POST",
               body={"title": title, "body": body, "labels": [LABEL]})
    print(f"created #{issue['number']}: {title}")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--scheduled", help="cron string of the run that fired")
    parser.add_argument("--start", type=date.fromisoformat)
    parser.add_argument("--end", type=date.fromisoformat)
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--now", type=datetime.fromisoformat,
                        help="pretend the scheduled run fired at this UTC time (testing)")
    args = parser.parse_args()
    repo = os.environ["GITHUB_REPOSITORY"]

    if args.scheduled:
        now = args.now.replace(tzinfo=timezone.utc) if args.now else datetime.now(timezone.utc)
        window = scheduled_window(args.scheduled, now)
        if window is None:
            print("skip: this run is not 4:00 PM in Chicago (the other Friday run is)")
            return
    elif args.start and args.end:
        window = manual_window(args.start, args.end)
    else:
        sys.exit("give --scheduled, or both --start and --end")

    title, body = render(*window, *collect(repo, *window))
    post(repo, title, body, args.dry_run)


if __name__ == "__main__":
    main()
